resume_fn="""async function resumeFirebaseClass(){const saved=readTeacherSession();if(!saved?.sessionId){toast('이어볼 실시간 수업이 없습니다.');return}try{const teacher=await ensureTeacherAuth(),ref=fbDb.collection('sessions').doc(saved.sessionId),snap=await ref.get();if(!snap.exists){clearTeacherSession();toast('저장된 수업을 찾지 못했습니다.');return}const d=snap.data()||{};if(d.teacherUid!==teacher.uid){toast('이 수업을 만든 교사 계정으로 로그인해 주세요.');return}const activity=d.activity||getUser()?.activities?.[d.activityId];if(!activity?.blocks?.length){toast('수업 활동 정보를 불러오지 못했습니다.');return}state.activity=clone(activity);state.selected=state.activity.blocks[0]?.id||null;state.screen='editor';state.sessionSetup={id:ref.id,firebaseSessionId:ref.id,activityId:d.activityId||activity.id,activityTitle:d.activityTitle||activity.title,blockIds:Array.isArray(d.blockIds)?d.blockIds:activity.blocks.map(b=>b.id),code:saved.code||'',status:d.status||'draft',mode:'firebase',currentBlock:Number.isInteger(d.currentBlock)?d.currentBlock:0,entryOpen:!!d.entryOpen,participants:[],responses:{},meetingHistory:Array.isArray(d.meetingHistory)?d.meetingHistory:[]};state.facilitatorPreview=d.status==='running'||d.status==='ended';rememberTeacherSession({sessionId:ref.id,activityId:d.activityId||activity.id,activityTitle:d.activityTitle||activity.title,code:saved.code||'',status:d.status||'draft'});subscribeTeacherFirebaseSession(ref.id);render();toast(d.status==='ended'?'지난 수업 결과를 불러왔습니다.':'실시간 수업에 다시 연결했습니다.')}catch(e){console.error(e);toast(firebaseErrorMessage(e))}}\n"""
