newjoin="""async function joinFirebaseSession(){const code=(document.querySelector('[data-student-code]')?.value||'').replace(/\\D/g,'').slice(0,6),name=(document.querySelector('[data-student-name]')?.value||'').trim().slice(0,20);if(code.length!==6){toast('6자리 참여 코드를 입력해 주세요.');return}if(!name){toast('이름을 입력해 주세요.');return}try{const user=await ensureAnonymousAuth(),codeSnap=await fbDb.collection('joinCodes').doc(code).get();if(!codeSnap.exists){toast('참여 코드를 찾지 못했습니다.');return}const sessionId=codeSnap.data().sessionId,sessionRef=fbDb.collection('sessions').doc(sessionId),partRef=sessionRef.collection('participants').doc(user.uid),partSnap=await partRef.get();let sessionSnap;try{sessionSnap=await sessionRef.get()}catch(e){if(e?.code==='permission-denied'&&!partSnap.exists){toast('학생 입장이 닫혔거나 종료된 수업입니다.');return}throw e}if(!sessionSnap.exists){toast('수업을 찾지 못했습니다.');return}const sd=sessionSnap.data()||{};if(partSnap.exists){const pd=partSnap.data()||{};await partRef.update({lastSeen:firebase.firestore.FieldValue.serverTimestamp()}).catch(()=>{});rememberStudentJoin(code,{sessionId,name:pd.name||name});attachStudentSession(sessionRef,user,{joined:true,sessionId,name:pd.name||name,activityTitle:sd.activityTitle||'수업',sessionStatus:sd.status||'draft',currentBlock:Number.isInteger(sd.currentBlock)?sd.currentBlock:0,activity:sd.activity||null,responses:{blocks:{}},participant:pd});toast('기존 수업으로 다시 연결했습니다.');return}if(sd.status==='ended'){toast('이미 종료된 수업입니다.');return}if(!sd.entryOpen){toast('현재 학생 입장이 닫혀 있습니다.');return}await partRef.set({uid:user.uid,name,role:'student',status:'waiting',currentBlock:0,joinedAt:firebase.firestore.FieldValue.serverTimestamp(),lastSeen:firebase.firestore.FieldValue.serverTimestamp()});rememberStudentJoin(code,{sessionId,name});attachStudentSession(sessionRef,user,{joined:true,sessionId,name,activityTitle:sd.activityTitle||'수업',sessionStatus:sd.status||'draft',currentBlock:Number.isInteger(sd.currentBlock)?sd.currentBlock:0,activity:sd.activity||null,responses:{blocks:{}},participant:null})}catch(e){console.error(e);toast(firebaseErrorMessage(e))}}\nfunction oneSelected"""
